@startuml

class HospitalHouseMD {
  + Name : string
}

class Patient {
  + Name : string
  + Symptoms : string
}

class Doctor {
  + Name : string
  + PractitionerNumber : int
}

class Diagnosis {
  + Description : string
  + IsApproved : boolean
}

class Treatment {
  + Name : string
  + Description : string
}

class ConsentForm {
  + Signature : string
  + DateSigned : datetime
}

class Illness {
  + Name : string
  + PriorityScore : PriorityScore
}

enum PriorityScore {
  High
  Low
}

class TreatmentStage {
  + StageLevel : int
}

HospitalHouseMD "1" -- "1..*" Patient
Patient "1" -- "1..*" Doctor
Patient "1" -- "0..*" Diagnosis
Doctor "1" -- "0..*" Diagnosis
Diagnosis "1" -- "1" Illness
Illness "1" -- "0..*" Treatment
Diagnosis "1" -- "0..*" Treatment
Patient "1" -- "0..*" ConsentForm
ConsentForm "1" -- "0..*" Treatment
Treatment "1" -- "1" TreatmentStage

@enduml

